SELECT "sk_dateid", "datevalue", "datedesc", "calendaryearid", "calendaryeardesc", "calendarqtrid", "calendarqtrdesc", "calendarmonthid", "calendarmonthdesc", "calendarweekid", "calendarweekdesc", "dayofweeknum", "dayofweekdesc", "fiscalyearid", "fiscalyeardesc", "fiscalqtrid", "fiscalqtrdesc", "holidayflag" FROM (SELECT TRY_CAST((CAST(b1.SK_DateID AS INT)) AS INT) AS "sk_dateid", TRY_CAST((TRY_CAST(b1.DateValue AS DATE)) AS DATE) AS "datevalue", TRY_CAST((CAST(b1.DateDesc AS TEXT)) AS TEXT) AS "datedesc", TRY_CAST((b1.CalendarYearID) AS DECIMAL(4)) AS "calendaryearid", TRY_CAST((CAST(b1.CalendarYearDesc AS TEXT)) AS TEXT) AS "calendaryeardesc", TRY_CAST((b1.CalendarQtrID) AS DECIMAL(5)) AS "calendarqtrid", TRY_CAST((CAST(b1.CalendarQtrDesc AS TEXT)) AS TEXT) AS "calendarqtrdesc", TRY_CAST((b1.CalendarMonthID) AS DECIMAL(6)) AS "calendarmonthid", TRY_CAST((CAST(b1.CalendarMonthDesc AS TEXT)) AS TEXT) AS "calendarmonthdesc", TRY_CAST((b1.CalendarWeekID) AS DECIMAL(6)) AS "calendarweekid", TRY_CAST((CAST(REPLACE(b1.CalendarWeekDesc, '-', ' -') AS TEXT)) AS TEXT) AS "calendarweekdesc", TRY_CAST((b1.DayOfWeekNum) AS DECIMAL(1)) AS "dayofweeknum", TRY_CAST((b1.DayOfWeekDesc) AS TEXT) AS "dayofweekdesc", TRY_CAST((b1.FiscalYearID) AS DECIMAL(4)) AS "fiscalyearid", TRY_CAST((CAST(b1.FiscalYearDesc AS TEXT)) AS TEXT) AS "fiscalyeardesc", TRY_CAST((b1.FiscalQtrID) AS DECIMAL(5)) AS "fiscalqtrid", TRY_CAST((CAST(b1.FiscalQtrDesc AS TEXT)) AS TEXT) AS "fiscalqtrdesc", TRY_CAST((TRY_CAST(b1.HolidayFlag AS BOOLEAN)) AS BOOLEAN) AS "holidayflag" FROM "Source"."Date" AS b1);
